<source_code>
import java.io.*;
import java.util.*;

public class Codeforces
{
    public static void main(String args[])throws Exception
    {
        BufferedReader bu=new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb=new StringBuilder();
        String s[]=bu.readLine().split(" ");
        int n=Integer.parseInt(s[0]);
        int i; double p=Double.parseDouble(s[1]);

        for(i=0;i<=n;i++)
        if(probab(n,i)>=p) break;
        System.out.println(i);
    }

    static int ncr(int n,int r)
    {
        if(r>n) return 0;
        int ans=1,i;
        for(i=n;i>n-r;i--) ans*=i;
        for(i=2;i<=r;i++) ans/=i;
        return ans;
    }

    static double probab(int n,int x)
    {
        int a=ncr(x,3)*ncr(n-x,0);
        int b=ncr(x,2)*ncr(n-x,1);
        int c=ncr(x,1)*ncr(n-x,2);
        return 1.0*((3.0/6)*c+a+b)/ncr(n,3);
    }
}
</source_code>
